def build_entry(creature):
    cid, no, baseId, bossId, name, types, hp, atk, spatk, def_, spdef, spd, aname, adesc, ivs, nname, boost, reduce = creature

    types_str = ", ".join(f'"{t}"' for t in types)

    ivs_parts = ", ".join(f'{k}: {v}' for k, v in ivs.items())

    moves = MOVES.get(name, [])

    has_data = hp > 0 or len(moves) > 0

    lines = []
    lines.append("  {")
    lines.append(f'    id: "{cid}",')
    lines.append(f'    no: "{no}",')
    if bossId:
        lines.append(f'    bossId: "{bossId}",')
    lines.append(f'    form: "regional",')
    lines.append(f'    baseId: "{baseId}",')
    lines.append(f'    name: "{name}",')
    lines.append(f'    types: [{types_str}],')
    lines.append(f'    image: "assets/creatures/{name}.png",')
    lines.append(f'    baseStats: {{ hp: {hp}, atk: {atk}, spatk: {spatk}, def: {def_}, spdef: {spdef}, spd: {spd} }},')
    lines.append(f'    ability: {{ name: "{aname}", desc: "{adesc}", icon: "assets/icons/abilities/{aname}.png" }},')
    lines.append(f'    ivs: {{ {ivs_parts} }},')
    lines.append(f'    nature: {{ name: "{nname}", boost: "{boost}", reduce: "{reduce}" }},')
    lines.append(f'    commonMoves: [],')
    if moves:
        # Format learnableMoves with ~8 moves per line
        move_strs = [f'"{m}"' for m in moves]
        chunk_size = 8
        chunks = [move_strs[i:i+chunk_size] for i in range(0, len(move_strs), chunk_size)]
        lines.append(f'    learnableMoves: [')
        for chunk in chunks:
            lines.append(f'      {", ".join(chunk)},')
        lines.append(f'    ],')
    else:
        lines.append(f'    learnableMoves: [],')
    lines.append("  },")

    return "\n".join(lines)


def find_last_entry_end(content_lines, target_no):
    """Find the line index (0-based) of the closing '  },' for the last entry with target_no."""
    last_end = -1
    i = 0
    while i < len(content_lines):
        # Check if this line has the target no
        if re.match(r'\s+no:\s+"' + re.escape(target_no) + r'"\s*,?\s*$', content_lines[i]):
            # Found an entry with this NO. Now find its closing '  },'
            # The closing is the first '  },' after we've tracked the depth
            j = i
            # Scan backwards to find the opening '{' of this entry
            k = i - 1
            while k >= 0:
                if re.match(r'^  \{', content_lines[k]):
                    break
                k -= 1
            # Now scan forward from k to find the closing
            depth = 0
            j = k
            while j < len(content_lines):
                stripped = content_lines[j].strip()
                if stripped == '{' or stripped.endswith('{') and not stripped.startswith('//'):
                    if re.match(r'^  \{', content_lines[j]) or re.match(r'^\s+\w+.*\{$', content_lines[j]):
                        depth += stripped.count('{') - stripped.count('}')
                    else:
                        depth += stripped.count('{') - stripped.count('}')
                elif stripped:
                    depth += stripped.count('{') - stripped.count('}')

                if depth == 0 and j > k and re.match(r'^  \},?\s*$', content_lines[j]):
                    last_end = j
                    break
                j += 1
        i += 1
    return last_end


# Read file
with open(r'D:\DmgCalculator\data\creatures.js', 'r', encoding='utf-8') as f:
    content = f.read()

lines = content.split('\n')
print(f"File has {len(lines)} lines")

# Build insertion map: no -> list of entries to insert (in order)
from collections import defaultdict
insertions = defaultdict(list)
for c in CREATURES:
    insertions[c[1]].append(build_entry(c))

# Process each NO group, find insertion point
# We need to process from bottom to top (highest NO first) to preserve line numbers
nos_sorted = sorted(set(c[1] for c in CREATURES), reverse=True)

for no in nos_sorted:
    end_idx = find_last_entry_end(lines, no)
    if end_idx == -1:
        print(f"WARNING: Could not find insertion point for NO {no}")
        continue

    print(f"NO {no}: inserting {len(insertions[no])} entries after line {end_idx + 1}")

    # Build the insertion text
    insert_text = "\n".join(insertions[no])
    insert_lines = insert_text.split('\n')

    # Insert after end_idx
    lines = lines[:end_idx+1] + insert_lines + lines[end_idx+1:]

# Write back
new_content = '\n'.join(lines)
with open(r'D:\DmgCalculator\data\creatures.js', 'w', encoding='utf-8') as f:
    f.write(new_content)

print(f"Done! File now has {len(lines)} lines")
